 for n,z in paths.items():rows.append(dict(study=n,scope='105-knot pre-contact path',clearance_mm=z['min_clearance_m']*1000,command_time_s=z['minimum_time_for_this_command_polyline_at015_s'],geometry_passed=z['model_geometry_passed'],commands_passed=z['model_command_passed'],timing_passed=z['command_schedule_passed'],physical_passed=False,failed_knots=z['failed_knots']))
 rows.extend([dict(study='82/83',scope='Same path77; optimized assumed foot forces',clearance_mm=paths['77']['min_clearance_m']*1000,command_time_s=force['summary']['minimum_command_polyline_time_s'],geometry_passed=True,commands_passed=True,timing_passed=True,filter_passed=filt['unclipped_inverse_filter_gate'],physical_passed=False),dict(study='84',scope='Zero-gap contact plus assumed0.1BW normal loading',clearance_mm=contact['summary']['minimum_housing_clearance_mm'],transition_passed=contact['summary']['complete_sampled_transition_passed'],physical_passed=False),dict(study='86',scope='Zero-gap endpoint; rear landing bound120mm',clearance_mm=stance['summary']['housing_clearance_mm'],endpoint_passed=stance['summary']['endpoint_model_passed'],physical_passed=False),dict(study='89',scope='Zero-gap endpoint; rear landing bound140mm',clearance_mm=last['summary']['housing_clearance_mm'],endpoint_passed=last['summary']['endpoint_model_passed'],physical_passed=False)])
 fig,axes=plt.subplots(1,2,figsize=(13,4.8));labels=['Path75','Path77','Path80','Forces82'];times=[paths[n]['minimum_time_for_this_command_polyline_at015_s'] for n in ['75','77','80']]+[force['summary']['minimum_command_polyline_time_s']];axes[0].barh(labels,times,color=['#b96552']*3+['#b68a35']);axes[0].axvline(13.5,ls='--',c='#333');axes[0].set_xlim(12.8,14.7);axes[0].set_xlabel('Specific model-command traversal time (s)');axes[0].set_title('Bare command timing excludes filter and contact');
